// Real waveform peaks + speech bounds for each Eleven v3 cue, and the course profile, as one ES module for the beats.
import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const R = '/tmp/rd-9f1df009', OUT = process.argv[2];
const voice = {};
for (const n of ['mi3', 'hill', 'ocean', 'board']) {
  const pcm = execSync(`ffmpeg -loglevel error -i ${R}/voice/${n}.mp3 -ac 1 -ar 16000 -f f32le -`, { maxBuffer: 1 << 26 });
  const f = new Float32Array(pcm.buffer, pcm.byteOffset, pcm.length / 4);
  const dur = f.length / 16000, BINS = 140, per = Math.floor(f.length / BINS);
  const pk = [];
  for (let b = 0; b < BINS; b++) { let s = 0; for (let i = b * per; i < (b + 1) * per; i++) s += f[i] * f[i]; pk.push(Math.sqrt(s / per)); }
  const mx = Math.max(...pk); const peaks = pk.map((v) => +(v / mx).toFixed(3));
  const on = peaks.findIndex((v) => v > 0.08), off = BINS - 1 - [...peaks].reverse().findIndex((v) => v > 0.08);
  const { text } = JSON.parse(readFileSync(`${R}/voice/${n}.json`, 'utf8'));
  voice[n] = { text, dur: +dur.toFixed(3), on: +(on / BINS * dur).toFixed(3), off: +((off + 1) / BINS * dur).toFixed(3), peaks };
}
const profile = JSON.parse(readFileSync(`${R}/profile.9f1df009.json`, 'utf8'));
writeFileSync(OUT, `// generated by peaks.9f1df009.mjs: the Eleven v3 cues' real RMS envelopes and the course profile Blender exported
// from the DEM (ft every 0.1 mi, path = the course xy normalised to its longer side). Do not hand-edit.
export const VOICE = ${JSON.stringify(voice)};
export const PROFILE = ${JSON.stringify(profile)};
`);
console.log(Object.entries(voice).map(([k, v]) => `${k} ${v.dur}s speech ${v.on}-${v.off}`).join('\n'));
